=== FILE: tb/tb_repro_data_byte.v ===
`timescale 1ns / 1ps
module tb_repro_data_byte;
    reg clk = 1'b0;
    reg rst = 1'b1;
    reg start = 1'b0;
    reg [7:0] data = 8'd0;
    wire tx, busy;
    integer passed = 0, failed = 0, i, guard;
    reg [8*64-1:0] nonce;

    uart_frame_tx #(.CLKS_PER_BIT(4)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data), .tx(tx), .busy(busy));

    always #5 clk = ~clk;

    task send_and_check(input [7:0] d);
        begin
            @(negedge clk); data = d; start = 1'b1;
            @(posedge clk); #1 start = 1'b0;
            repeat (2) @(posedge clk); #1;           // centre of start bit
            for (i = 0; i < 8; i = i + 1) begin
                repeat (4) @(posedge clk); #1;       // centre of data bit i
                if (tx === d[i]) passed = passed + 1;
                else begin
                    failed = failed + 1;
                    $display("CHECK data_bit_order FAIL byte=%h bit=%0d tx=%b exp=%b", d, i, tx, d[i]);
                end
            end
            guard = 0;
            while (busy && guard < 200) begin @(posedge clk); #1; guard = guard + 1; end
            repeat (3) @(posedge clk);
        end
    endtask

    initial begin
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "none";
        repeat (4) @(posedge clk);
        #1 rst = 1'b0;
        repeat (2) @(posedge clk);
        send_and_check(8'h01);
        send_and_check(8'hA3);
        send_and_check(8'h35);
        send_and_check(8'hF0);
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule
=== END FILE ===
