`timescale 1ns / 1ps
module tb_repro_frame_period;
    localparam integer CPB = 4;
    reg clk = 1'b0;
    reg rst = 1'b1;
    reg start = 1'b0;
    reg [7:0] data = 8'd0;
    wire tx, busy;
    integer passed = 0, failed = 0, count;
    reg [8*64-1:0] nonce;

    uart_frame_tx #(.CLKS_PER_BIT(CPB)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data), .tx(tx), .busy(busy));

    always #5 clk = ~clk;

    task send_and_check(input [7:0] d);
        begin
            @(negedge clk); data = d; start = 1'b1;
            @(posedge clk); #1 start = 1'b0;
            count = 0;
            while (busy && count < 200) begin @(posedge clk); #1; count = count + 1; end
            if (count == 11 * CPB) passed = passed + 1;
            else begin
                failed = failed + 1;
                $display("CHECK frame_period FAIL byte=%h busy_cycles=%0d exp=%0d", d, count, 11 * CPB);
            end
            repeat (3) @(posedge clk);
        end
    endtask

    initial begin
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "none";
        repeat (4) @(posedge clk);
        #1 rst = 1'b0;
        repeat (2) @(posedge clk);
        send_and_check(8'h55);
        send_and_check(8'hC3);
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule
